UPDATE wms_location
warehouse_id = #{warehouseId}, area_id = #{areaId}, location_code = #{locationCode}, location_name = #{locationName}, location_type = #{locationType}, row_num = #{rowNum}, column_num = #{columnNum}, layer_num = #{layerNum}, max_capacity = #{maxCapacity}, current_quantity = #{currentQuantity}, available_capacity = #{availableCapacity}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT

FROM wms_location l
LEFT JOIN wms_warehouse w ON l.warehouse_id = w.id
LEFT JOIN wms_area a ON l.area_id = a.id

    AND l.warehouse_id = #{warehouseId}
    AND l.area_id = #{areaId}
    AND l.status = #{status}
    AND l.location_type = #{locationType}

ORDER BY l.row_num, l.column_num, l.layer_num

SELECT

FROM wms_location l
LEFT JOIN wms_warehouse w ON l.warehouse_id = w.id
LEFT JOIN wms_area a ON l.area_id = a.id

    l.warehouse_id = #{warehouseId}
    AND l.area_id = #{areaId}
    AND l.status = 1
    AND l.available_capacity >= #{requiredCapacity}
    AND l.location_type = #{productType}

ORDER BY l.available_capacity DESC
